import hashlib
import os
from datetime import date

def register_staff(username: str, pin: str) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdecimal()):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations).hex()
    return {'username': username, 'salt': salt.hex(), 'digest': digest, 'iterations': iterations}

def verify_staff_pin(record: dict, pin: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(pin, str):
            return False
        salt = bytes.fromhex(record['salt'])
        digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, int(record['iterations'])).hex()
        return digest == record['digest']
    except (KeyError, TypeError, ValueError):
        return False

def summarize_inventory(items: list[dict], as_of: str, blood_group: str | None=None, page: int=1, page_size: int=10) -> dict:
    groups = {'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'}
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if blood_group is not None and blood_group not in groups:
        raise ValueError('invalid blood group')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    totals = {}
    counts = {}
    for item in items:
        if not isinstance(item, dict) or item.get('blood_group') not in groups or (not isinstance(item.get('units'), int)) or isinstance(item.get('units'), bool) or (item.get('units') < 0):
            raise ValueError('invalid item')
        try:
            expiry = date.fromisoformat(item['expires'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid date')
        if blood_group is not None and item['blood_group'] != blood_group:
            continue
        if expiry >= cutoff and item['units'] > 0:
            key = item['blood_group']
            totals[key] = totals.get(key, 0) + item['units']
            counts[key] = counts.get(key, 0) + 1
    ordered = sorted(totals, key=lambda key: (-totals[key], key))
    start = (page - 1) * page_size
    selected = [{'blood_group': key, 'units': totals[key], 'lots': counts[key]} for key in ordered[start:start + page_size]]
    return {'total_units': sum(totals.values()), 'total_groups': len(ordered), 'page': page, 'page_size': page_size, 'groups': selected}

