import math
import requests

def search_freelancer_gigs(query: str, min_budget: float=0, page: int=1, per_page: int=10) -> list[dict]:
    if not isinstance(query, str):
        raise TypeError('query must be a string')
    if not query.strip():
        raise ValueError('query must not be empty')
    if isinstance(min_budget, bool) or not isinstance(min_budget, (int, float)):
        raise TypeError('min_budget must be numeric')
    if not math.isfinite(min_budget) or min_budget < 0:
        raise ValueError('invalid min_budget')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(per_page, bool) or not isinstance(per_page, int) or (not 1 <= per_page <= 50):
        raise ValueError('invalid per_page')
    response = requests.get('https://api.freelance.example/v1/gigs', params={'query': query, 'page': page, 'per_page': per_page}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    data = response.json()
    rows = data.get('results', []) if isinstance(data, dict) else []
    wanted = query.casefold()
    found = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        title = row.get('title')
        budget = row.get('budget')
        skills = row.get('skills')
        rating = row.get('client_rating')
        if not isinstance(title, str) or isinstance(budget, bool) or (not isinstance(budget, (int, float))) or (not isinstance(skills, list)) or isinstance(rating, bool) or (not isinstance(rating, (int, float))):
            continue
        text = ' '.join([title, str(row.get('description', ''))] + [str(s) for s in skills])
        if budget >= min_budget and wanted in text.casefold():
            found.append({'title': title, 'budget': round(budget, 2), 'skills': skills, 'client_rating': round(rating, 2)})
    found.sort(key=lambda x: (-x['budget'], -x['client_rating'], x['title'].casefold()))
    start = (page - 1) * per_page
    return found[start:start + per_page]

