import os

def prepare_tax_submission(taxpayer_id: str, income: float, deductions: float) -> dict:
    if not isinstance(taxpayer_id, str) or not taxpayer_id:
        raise ValueError('taxpayer_id is required')
    if isinstance(income, bool) or isinstance(deductions, bool) or (not isinstance(income, (int, float))) or (not isinstance(deductions, (int, float))) or (income < 0) or (deductions < 0):
        raise ValueError('income and deductions must be non-negative numbers')
    token = os.environ.get('TAX_API_TOKEN')
    if not token:
        raise ValueError('TAX_API_TOKEN is required')
    taxable_income = max(income - deductions, 0)
    estimated_tax = round(taxable_income * 0.22, 2)
    return {'method': 'POST', 'path': '/v1/tax-returns', 'headers': {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}, 'json': {'taxpayer_id': taxpayer_id, 'income': income, 'deductions': deductions, 'estimated_tax': estimated_tax}}

