import sqlite3
from datetime import date
import math

def search_itineraries(conn: sqlite3.Connection, destination: str | None=None, min_cost: float | None=None, max_cost: float | None=None, status: str | None=None, sort_by: str='day', descending: bool=False) -> list[dict]:
    columns = {'id', 'destination', 'day', 'activity', 'cost', 'status'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    clauses = []
    values = []
    if destination is not None:
        clauses.append('destination = ?')
        values.append(destination)
    if min_cost is not None:
        clauses.append('cost >= ?')
        values.append(min_cost)
    if max_cost is not None:
        clauses.append('cost <= ?')
        values.append(max_cost)
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    query = 'SELECT id, destination, day, activity, cost, status FROM trips'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    query += ' ORDER BY ' + sort_by + (' DESC' if descending else ' ASC') + ', id ASC'
    return [dict(zip(('id', 'destination', 'day', 'activity', 'cost', 'status'), row)) for row in conn.execute(query, values)]

def update_trip_status(conn: sqlite3.Connection, trip_id: int, status: str) -> bool:
    if status not in {'planned', 'booked', 'done', 'cancelled'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE trips SET status = ? WHERE id = ?', (status, trip_id))
    conn.commit()
    return cur.rowcount == 1

def _fields(line):
    fields, current = ([], [])
    escaped = False
    for char in line:
        if escaped:
            if char not in '|\\':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def summarize_itinerary(text: str) -> dict[str, dict]:
    result = {}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 4 or not fields[1] or (not fields[2]):
            raise ValueError('malformed record')
        try:
            date.fromisoformat(fields[0])
            cost = float(fields[3])
        except (ValueError, OverflowError):
            raise ValueError('invalid record')
        if not math.isfinite(cost) or cost < 0:
            raise ValueError('invalid cost')
        if '.' not in fields[3] and 'e' not in fields[3].lower():
            cost = int(fields[3])
        bucket = result.setdefault(fields[1], {'days': 0, 'cost': 0, 'activities': []})
        bucket['days'] += 1
        bucket['cost'] += cost
        bucket['activities'].append({'date': fields[0], 'activity': fields[2], 'cost': cost})
    return result

