import sqlite3
_STATUSES = ('pending', 'approved', 'rejected')
_SORTS = {'id': 'id', 'applicant': 'applicant', 'program': 'program', 'status': 'status', 'amount': 'amount', 'submitted': 'submitted'}

def list_grants(conn: sqlite3.Connection, status: str | None=None, search: str | None=None, sort: str='submitted', descending: bool=False, limit: int | None=None, offset: int=0) -> list[dict]:
    if status is not None and status not in _STATUSES:
        raise ValueError('invalid status')
    if sort not in _SORTS:
        raise ValueError('invalid sort')
    if isinstance(limit, bool) or (limit is not None and (not isinstance(limit, int) or limit <= 0)):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    clauses = []
    params = []
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if search is not None:
        clauses.append('(lower(applicant) like lower(?) or lower(program) like lower(?))')
        params.extend(('%' + search + '%', '%' + search + '%'))
    sql = 'select id, applicant, program, status, amount, submitted from grants'
    if clauses:
        sql += ' where ' + ' and '.join(clauses)
    direction = ' desc' if descending else ' asc'
    sql += ' order by ' + _SORTS[sort] + direction + ', id asc'
    if limit is not None:
        sql += ' limit ? offset ?'
        params.extend((limit, offset))
    elif offset:
        sql += ' limit -1 offset ?'
        params.append(offset)
    rows = conn.execute(sql, params).fetchall()
    keys = ('id', 'applicant', 'program', 'status', 'amount', 'submitted')
    return [dict(zip(keys, row)) for row in rows]

def set_grant_status(conn: sqlite3.Connection, grant_id: int, new_status: str) -> bool:
    if new_status not in _STATUSES:
        raise ValueError('invalid status')
    cur = conn.execute('update grants set status = ? where id = ?', (new_status, grant_id))
    conn.commit()
    return cur.rowcount != 0

def grant_summary(conn: sqlite3.Connection) -> dict[str, dict[str, float | int]]:
    result = {}
    rows = conn.execute('select status, count(*), coalesce(sum(amount), 0.0), coalesce(avg(amount), 0.0) from grants group by status').fetchall()
    values = {row[0]: row[1:] for row in rows}
    for status in _STATUSES:
        count, total, average = values.get(status, (0, 0.0, 0.0))
        result[status] = {'count': int(count), 'total_amount': float(total), 'average_amount': float(average)}
    return result

