    parser = etree.XMLParser(resolve_entities=True, load_dtd=True)
    try:
        return etree.fromstring(xml.encode('utf-8'), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _text(node):
    return (node.text or '').strip()

def parse_applications(xml: str) -> list[dict]:
    root = _read(xml)
    if root.tag != 'feed':
        raise ValueError('invalid root')
    output = []
    for app in root.findall('application'):
        if len(app.findall('candidate')) != 1 or len(app.findall('stage')) != 1 or len(app.findall('skills')) > 1:
            raise ValueError('invalid application structure')
        required = ('id', 'role', 'score', 'applied')
        if any((not (app.get(k) or '').strip() for k in required)):
            raise ValueError('missing attribute')
        score_text = app.get('score').strip()
        try:
            score = float(score_text)
        except Exception as exc:
            raise ValueError('invalid score') from exc
        if score < 0 or score > 100:
            raise ValueError('invalid score')
        applied = app.get('applied').strip()
        try:
            datetime.strptime(applied, '%Y-%m-%dT%H:%M:%SZ')
        except Exception as exc:
            raise ValueError('invalid date') from exc
        candidate = app.find('candidate')
        names = candidate.findall('name')
        emails = candidate.findall('email')
        if len(names) != 1 or len(emails) != 1 or (not _text(names[0])) or (not _text(emails[0])):
            raise ValueError('invalid candidate')
        stage = _text(app.find('stage'))
        if not stage:
            raise ValueError('invalid stage')
        skills = []
        seen = set()
        skills_node = app.find('skills')
        if skills_node is not None:
            for skill in skills_node.findall('skill'):
                value = _text(skill)
                key = value.casefold()
                if value and key not in seen:
                    seen.add(key)
                    skills.append(value)
        output.append({'id': app.get('id').strip(), 'role': app.get('role').strip(), 'score': score, 'applied': applied, 'name': _text(names[0]), 'email': _text(emails[0]), 'stage': stage, 'skills': skills})
    output.sort(key=lambda x: (-x['score'], x['applied'], x['id']))
    return output

def summarize_pipeline(xml: str, role: str) -> dict:
    records = [x for x in parse_applications(xml) if x['role'] == role]
    stages = {}
    for record in records:
        stages[record['stage']] = stages.get(record['stage'], 0) + 1
    stages = dict(sorted(stages.items()))
    average = round(sum((x['score'] for x in records)) / len(records), 2) if records else 0.0
    return {'count': len(records), 'average_score': average, 'by_stage': stages, 'top': [x['id'] for x in records[:3]]}

