            raise ValueError('invalid event')
        try:
            datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
        except Exception as exc:
            raise ValueError('invalid time') from exc
        vehicles = [x for x in node if x.tag == 'vehicle']
        if len(vehicles) > 1 or (vehicles and (not vehicles[0].attrib.get('plate'))):
            raise ValueError('invalid vehicle')
        plate = vehicles[0].attrib['plate'] if vehicles else None
        result.append({'ticket': ticket, 'kind': kind, 'time': stamp, 'level': level, 'plate': plate})
    return result

def parse_feed(xml_text: str) -> list[dict[str, object]]:
    return _events(xml_text)

def build_report(xml_text: str, hourly_rate: float) -> dict[str, object]:
    if not math.isfinite(hourly_rate) or hourly_rate < 0:
        raise ValueError('invalid rate')
    events = _events(xml_text)
    decorated = []
    for index, event in enumerate(events):
        text = event['time']
        value = datetime.fromisoformat(text[:-1] + '+00:00' if text.endswith('Z') else text)
        decorated.append((value, index, event))
    decorated.sort(key=lambda item: (item[0], item[1]))
    active = {}
    sessions = []
    peak = 0
