        ticket = event['ticket']
        if event['kind'] == 'enter':
            if ticket in active:
                raise ValueError('duplicate entry')
            active[ticket] = (when, event['level'])
        else:
            if ticket not in active:
                raise ValueError('unmatched exit')
            started, level = active.pop(ticket)
            seconds = (when - started).total_seconds()
            if seconds <= 0:
                raise ValueError('invalid interval')
            minutes = int(seconds // 60)
            hours = max(1, (minutes + 59) // 60)
            charge = float((Decimal(str(hourly_rate)) * Decimal(hours)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
            sessions.append({'ticket': ticket, 'level': level, 'minutes': minutes, 'charge': charge})
        peak = max(peak, len(active))
    if active:
        raise ValueError('open entry')
    sessions.sort(key=lambda item: next((i for i, x in enumerate(decorated) if x[2]['ticket'] == item['ticket'] and x[2]['kind'] == 'enter'), 0))
    levels = {}
    for session in sessions:
        level = session['level']
        bucket = levels.setdefault(level, {'visits': 0, 'minutes': 0, 'revenue': 0.0})
        bucket['visits'] += 1
        bucket['minutes'] += session['minutes']
        bucket['revenue'] = round(bucket['revenue'] + session['charge'], 2)
    return {'sessions': sessions, 'peak_occupancy': peak, 'by_level': {k: levels[k] for k in sorted(levels)}}

