from datetime import datetime

def summarize_telemetry(requester: dict, satellite: dict, readings: list[dict]) -> dict:
    if not isinstance(requester, dict) or not all((k in requester for k in ('id', 'tenant_id', 'roles'))):
        raise ValueError('invalid requester')
    if not isinstance(satellite, dict) or not all((k in satellite for k in ('id', 'tenant_id', 'owner_id'))):
        raise ValueError('invalid satellite')
    if requester['id'] != satellite['owner_id'] and (not ('telemetry_admin' in requester['roles'] and requester['tenant_id'] == satellite['tenant_id'])):
        raise PermissionError('request not permitted')
    values = []
    latest = None
    for reading in readings:
        if not all((k in reading for k in ('timestamp', 'temperature_c', 'battery_percent'))):
            raise ValueError('invalid reading')
        if not isinstance(reading['temperature_c'], (int, float)) or isinstance(reading['temperature_c'], bool):
            raise ValueError('invalid temperature')
        if not isinstance(reading['battery_percent'], (int, float)) or isinstance(reading['battery_percent'], bool):
            raise ValueError('invalid battery')
        stamp = datetime.fromisoformat(reading['timestamp'].replace('Z', '+00:00'))
        values.append(reading['temperature_c'])
        if latest is None or stamp > latest[0]:
            latest = (stamp, reading['battery_percent'])
    count = len(values)
    return {'satellite_id': satellite['id'], 'reading_count': count, 'average_temperature_c': round(sum(values) / count, 2) if count else None, 'minimum_temperature_c': round(min(values), 2) if values else None, 'maximum_temperature_c': round(max(values), 2) if values else None, 'latest_battery_percent': latest[1] if latest else None}

