from solution import extract_and_summarize

import csv
import io
import tempfile
import zipfile
from pathlib import Path

import pytest


def make_archive(directory, files):
    archive = Path(directory) / "reports.zip"
    with zipfile.ZipFile(archive, "w") as zf:
        for name, content in files.items():
            zf.writestr(name, content)
    return str(archive)


def report(rows, header="date,category,amount"):
    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    writer.writerow(header.split(","))
    writer.writerows(rows)
    return output.getvalue()


def test_aggregates_inclusive_dates_and_rounds_half_up():
    with tempfile.TemporaryDirectory() as temp:
        archive = make_archive(temp, {
            "jan.csv": report([
                ["2024-01-01", "Travel", "1.005"],
                ["2024-01-31", "Meals", "2.50"],
                ["2024-02-01", "Travel", "9.99"],
            ])
        })
        result = extract_and_summarize(archive, str(Path(temp) / "out"), ["jan.csv"], "2024-01-01", "2024-01-31")
        assert result == {"Meals": 250, "Travel": 101}


def test_combines_members_and_sorts_categories():
    with tempfile.TemporaryDirectory() as temp:
        archive = make_archive(temp, {
            "b.csv": report([["2024-03-02", "Zeta", "1.00"], ["2024-03-03", "Alpha", "2.00"]]),
            "nested/a.csv": report([["2024-03-01", "Zeta", "3.25"], ["2024-03-04", "Beta", "0.00"]]),
        })
        result = extract_and_summarize(archive, str(Path(temp) / "out"), ["b.csv", "nested/a.csv"], "2024-03-01", "2024-03-04")
        assert result == {"Alpha": 200, "Beta": 0, "Zeta": 425}


def test_empty_inputs_and_nonmatching_rows():
    with tempfile.TemporaryDirectory() as temp:
        archive = make_archive(temp, {"empty.csv": report([["2020-01-01", "Old", "4.00"]])})
        out = str(Path(temp) / "created")
        assert extract_and_summarize(archive, out, [], "2024-01-01", "2024-01-31") == {}
        assert extract_and_summarize(archive, out, ["empty.csv"], "2024-01-01", "2024-01-31") == {}
        assert Path(out).is_dir()


def test_invalid_date_range_and_rows_raise_value_error():
    with tempfile.TemporaryDirectory() as temp:
        archive = make_archive(temp, {
            "bad.csv": report([["2024-01-xx", "A", "1.00"]]),
        })
        with pytest.raises(ValueError):
            extract_and_summarize(archive, temp, ["bad.csv"], "2024-02-01", "2024-01-01")
        with pytest.raises(ValueError):
            extract_and_summarize(archive, temp, ["bad.csv"], "2024-01-01", "2024-01-31")
        with pytest.raises(ValueError):
            extract_and_summarize(archive, temp, ["bad.csv"], "not-a-date", "2024-01-31")


def test_bad_header_and_amount_raise_value_error():
    with tempfile.TemporaryDirectory() as temp:
        archive = make_archive(temp, {
            "header.csv": report([["2024-01-01", "A", "1.00"]], "category,date,amount"),
            "amount.csv": report([["2024-01-01", "A", "oops"]]),
        })
        with pytest.raises(ValueError):
            extract_and_summarize(archive, temp, ["header.csv"], "2024-01-01", "2024-01-02")
        with pytest.raises(ValueError):
            extract_and_summarize(archive, temp, ["amount.csv"], "2024-01-01", "2024-01-02")


def test_missing_member_and_files_are_written():
    with tempfile.TemporaryDirectory() as temp:
        archive = make_archive(temp, {"reports/q1.csv": report([["2024-01-01", "Office", "12.34"]])})
        output = Path(temp) / "new" / "location"
        with pytest.raises(KeyError):
            extract_and_summarize(archive, str(output), ["missing.csv"], "2024-01-01", "2024-12-31")
        result = extract_and_summarize(archive, str(output), ["reports/q1.csv"], "2024-01-01", "2024-12-31")
        assert result == {"Office": 1234}
        assert (output / "reports" / "q1.csv").read_text() == report([["2024-01-01", "Office", "12.34"]])

