import csv
import io
import os
import zipfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path
from datetime import date

def extract_and_summarize(archive_path: str, output_dir: str, member_names: list[str], start_date: str, end_date: str) -> dict[str, int]:
    try:
        first = date.fromisoformat(start_date)
        last = date.fromisoformat(end_date)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if first > last:
        raise ValueError('invalid date range')
    base = Path(output_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    totals = {}
    with zipfile.ZipFile(archive_path) as archive:
        available = set(archive.namelist())
        for member in member_names:
            if member not in available:
                raise KeyError(member)
            target = (base / member).resolve()
            try:
                target.relative_to(base)
            except ValueError as exc:
                raise ValueError('invalid member path') from exc
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(member))
            with target.open(newline='', encoding='utf-8') as stream:
                reader = csv.DictReader(stream)
                if reader.fieldnames != ['date', 'category', 'amount']:
                    raise ValueError('invalid header')
                for row in reader:
                    try:
                        current = date.fromisoformat(row['date'])
                    except (ValueError, TypeError) as exc:
                        raise ValueError('invalid row date') from exc
                    if not row['category']:
                        raise ValueError('empty category')
                    try:
                        cents = int((Decimal(row['amount']) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
                    except (InvalidOperation, ValueError) as exc:
                        raise ValueError('invalid amount') from exc
                    if first <= current <= last:
                        totals[row['category']] = totals.get(row['category'], 0) + cents
    return {key: totals[key] for key in sorted(totals)}

