from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import re

def canonical_procedure(value: str) -> dict:
    if not isinstance(value, str):
        raise ValueError('invalid procedure')
    m = re.fullmatch('\\s*([DRXdrx]\\d{4})(?:\\s*/\\s*(\\d+))?\\s*', value)
    if not m:
        raise ValueError('invalid procedure')
    tooth = int(m.group(2)) if m.group(2) is not None else None
    if tooth is not None and (not 1 <= tooth <= 32):
        raise ValueError('invalid tooth')
    return {'code': m.group(1).upper(), 'tooth': tooth}

def _cents(value):
    try:
        d = Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid amount')
    if d < 0:
        raise ValueError('negative amount')
    return int(d * 100)

def _day(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    return value

def build_patient_statement(requester: dict, patient: dict, visits: list[dict], payments: list[dict]) -> dict:
    if not isinstance(requester, dict) or not isinstance(patient, dict):
        raise PermissionError('not permitted')
    roles = requester.get('roles', [])
    if requester.get('tenant_id') != patient.get('tenant_id') or not (requester.get('id') == patient.get('owner_id') or any((x in roles for x in ('dentist', 'billing', 'admin')))):
        raise PermissionError('not permitted')
    lines = []
    subtotal = paid = 0
    for item in visits:
        d = _day(item['date'])
        amount = _cents(item['fee'])
        proc = canonical_procedure(item['procedure'])
        lines.append({'date': d, 'kind': 'charge', 'procedure': proc, 'amount_cents': amount, 'note': item.get('note', '')})
        subtotal += amount
    for item in payments:
        d = _day(item['date'])
        amount = _cents(item['amount'])
        lines.append({'date': d, 'kind': 'payment', 'amount_cents': amount})
        paid += amount
    lines.sort(key=lambda x: (x['date'], 0 if x['kind'] == 'charge' else 1))
    return {'patient_id': patient['id'], 'patient_name': patient['name'], 'lines': lines, 'subtotal_cents': subtotal, 'paid_cents': paid, 'balance_cents': subtotal - paid}

