import os

def build_route_dispatch(records: list[dict], route_id: str, page: int, page_size: int) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('page and page_size must be positive integers')
    token = os.environ.get('STUDENT_TRANSPORT_API_TOKEN')
    if token is None:
        raise RuntimeError('STUDENT_TRANSPORT_API_TOKEN is required')
    groups = {}
    required = ('student_id', 'route_id', 'stop', 'status', 'eta_minutes', 'distance_km')
    for record in records:
        if any((key not in record for key in required)):
            raise ValueError('record is missing a required field')
        if record['status'] not in ('scheduled', 'cancelled') or any((not isinstance(record[key], str) or not record[key] for key in ('student_id', 'route_id', 'stop'))):
            raise ValueError('invalid record')
        if record['eta_minutes'] < 0 or record['distance_km'] < 0:
            raise ValueError('numeric values cannot be negative')
        if record['route_id'] == route_id and record['status'] == 'scheduled':
            groups.setdefault(record['stop'], []).append(record)
    stops = []
    for stop in sorted(groups):
        rows = sorted(groups[stop], key=lambda row: row['student_id'])
        stops.append({'stop': stop, 'students': [r['student_id'] for r in rows], 'student_count': len(rows), 'total_distance_km': round(sum((r['distance_km'] for r in rows)), 2), 'average_eta_minutes': round(sum((r['eta_minutes'] for r in rows)) / len(rows), 1)})
    start = (page - 1) * page_size
    return {'api_token': token, 'route_id': route_id, 'page': page, 'page_size': page_size, 'total_stops': len(stops), 'total_students': sum((x['student_count'] for x in stops)), 'stops': stops[start:start + page_size]}

