import math
import requests

def get_auction_lots(api_url: str, category: str | None, minimum_bid: float, max_pages: int) -> list[dict]:
    if not isinstance(max_pages, int) or isinstance(max_pages, bool) or max_pages <= 0:
        raise ValueError('max_pages must be positive')
    if not isinstance(minimum_bid, (int, float)) or isinstance(minimum_bid, bool) or (not math.isfinite(minimum_bid)) or (minimum_bid < 0):
        raise ValueError('minimum_bid is invalid')
    if category is not None and (not isinstance(category, str)):
        raise TypeError('category must be a string or None')
    found = {}
    for page in range(1, max_pages + 1):
        params = {'page': page, 'limit': 50}
        if category is not None:
            params['category'] = category
        response = requests.get(api_url, params=params, headers={'Accept': 'application/json'})
        if response.status_code != 200:
            raise ValueError('request failed')
        try:
            payload = response.json()
            items = payload['items']
            has_next = payload['next']
            if not isinstance(items, list) or not isinstance(has_next, bool):
                raise ValueError
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid response')
        for raw in items:
            try:
                identifier = raw['id']
                title = raw['title']
                seller = raw['seller']
                bid = float(raw['bid'])
                item_category = raw['category']
            except (KeyError, TypeError, ValueError):
                raise ValueError('invalid item')
            if not math.isfinite(bid):
                raise ValueError('invalid bid')
            if (category is None or item_category == category) and bid >= minimum_bid:
                candidate = {'id': identifier, 'title': title, 'seller': seller, 'bid': round(bid, 2)}
                if identifier not in found or bid > found[identifier]['bid']:
                    found[identifier] = {**candidate, 'bid': bid}
        if not has_next:
            break
    result = [{**value, 'bid': round(value['bid'], 2)} for value in found.values()]
    result.sort(key=lambda value: (-value['bid'], value['id']))
    return result

