import json
import os

def write_incident_report(base_dir: str, relative_name: str, incidents: list[dict]) -> str:
    if not isinstance(base_dir, str) or not isinstance(relative_name, str) or (not relative_name):
        raise ValueError('invalid path')
    if not isinstance(incidents, list):
        raise ValueError('incidents must be a list')
    severities = ['critical', 'high', 'medium', 'low']
    statuses = {'open', 'resolved'}
    seen = set()
    groups = {severity: [] for severity in severities}
    for incident in incidents:
        if not isinstance(incident, dict) or set(incident) != {'id', 'severity', 'status', 'resolution_minutes'}:
            raise ValueError('invalid incident')
        ident = incident['id']
        severity = incident['severity']
        status = incident['status']
        minutes = incident['resolution_minutes']
        if not isinstance(ident, str) or not ident or ident in seen:
            raise ValueError('invalid id')
        if severity not in severities or status not in statuses:
            raise ValueError('invalid incident category')
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes < 0:
            raise ValueError('invalid resolution time')
        seen.add(ident)
        groups[severity].append((status, minutes))
    summary = []
    for severity in severities:
        entries = groups[severity]
        resolved = [minutes for status, minutes in entries if status == 'resolved']
        summary.append({'severity': severity, 'total': len(entries), 'open': sum((status == 'open' for status, _ in entries)), 'resolved': len(resolved), 'average_resolution_minutes': round(sum(resolved) / len(resolved), 2) if resolved else 0.0})
    root = os.path.abspath(base_dir)
    destination = os.path.abspath(os.path.join(root, relative_name))
    if os.path.commonpath([root, destination]) != root:
        raise ValueError('invalid path')
    os.makedirs(os.path.dirname(destination), exist_ok=True)
    with open(destination, 'w', encoding='utf-8') as handle:
        json.dump({'total': len(incidents), 'by_severity': summary}, handle, indent=2)
        handle.write('\n')
    return destination

