import base64
import hashlib
import hmac
import os
from datetime import datetime, timezone

def make_user(username: str, password: str, roles: list[str]) -> dict:
    if not isinstance(username, str) or not username or any((c.isspace() for c in username)):
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(roles, list) or any((not isinstance(x, str) or not x for x in roles)):
        raise ValueError('invalid roles')
    if len(set(roles)) != len(roles):
        raise ValueError('duplicate roles')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    encoded = base64.b64encode(salt + value).decode()
    return {'username': username, 'roles': sorted(roles), 'password_hash': encoded}

def authenticate(user: dict, password: str) -> bool:
    if not isinstance(user, dict) or not isinstance(password, str):
        return False
    encoded = user.get('password_hash')
    if not isinstance(encoded, str):
        return False
    try:
        raw = base64.b64decode(encoded.encode(), validate=True)
        salt, expected = (raw[:16], raw[16:])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('trailing escape')
    out.append(''.join(cur))
    return out

def _time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid time')
    try:
        parsed = datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
    except ValueError:
        raise ValueError('invalid time')
    return parsed

def summarize_incidents(log: str, as_of: str) -> list[dict]:
    if not isinstance(log, str):
        raise ValueError('invalid log')
    cutoff = _time(as_of)
    groups = {}
    ranks = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
    states = {'open', 'acknowledged', 'resolved'}
    for line in log.splitlines():
        if not line.strip():
            continue
        fields = _fields(line)
        if len(fields) != 5:
            raise ValueError('invalid record')
        stamp, ident, severity, state, message = fields
        parsed = _time(stamp)
        if not ident or not message or severity not in ranks or (state not in states) or (parsed > cutoff):
            raise ValueError('invalid record')
        groups.setdefault(ident, []).append((parsed, severity, state, message))
    result = []
    for ident, events in groups.items():
        events.sort(key=lambda x: x[0])
        first, last = (events[0][0], events[-1][0])
        latest = events[-1]
        severity = max((x[1] for x in events), key=ranks.get)
        duration = (last - first).seconds if latest[2] == 'resolved' else (cutoff - first).seconds
        result.append({'incident_id': ident, 'severity': severity, 'state': latest[2], 'first_seen': first.strftime('%Y-%m-%dT%H:%M:%SZ'), 'last_seen': last.strftime('%Y-%m-%dT%H:%M:%SZ'), 'message': latest[3], 'duration_seconds': duration})
