from decimal import Decimal, InvalidOperation

def parse_cpu(value: str) -> int:
    if not isinstance(value, str):
        raise ValueError('invalid cpu')
    text = value.strip()
    if not text:
        raise ValueError('invalid cpu')
    try:
        if text.endswith('m'):
            number = Decimal(text[:-1])
            if number < 0 or number != number.to_integral_value():
                raise ValueError('invalid cpu')
            return int(number)
        number = Decimal(text)
        result = number * 1000
        if number < 0 or result != result.to_integral_value():
            raise ValueError('invalid cpu')
        return int(result)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid cpu')

def summarize_pods(pods: list[dict]) -> list[dict]:
    groups = {}
    for pod in pods:
        if not isinstance(pod, dict):
            raise ValueError('invalid pod')
        required = ['name', 'namespace', 'phase', 'cpu', 'restarts', 'created']
        if any((k not in pod for k in required)):
            raise ValueError('missing field')
        if any((not isinstance(pod[k], str) for k in ['name', 'namespace', 'phase', 'cpu', 'created'])):
            raise ValueError('invalid field')
        if isinstance(pod['restarts'], bool) or not isinstance(pod['restarts'], int) or pod['restarts'] < 0:
            raise ValueError('invalid restarts')
        try:
            stamp = datetime.fromisoformat(pod['created'].replace('Z', '+00:00'))
            if not pod['created'].endswith('Z') or stamp.tzinfo is None:
                raise ValueError
        except ValueError:
            raise ValueError('invalid timestamp')
        ns = pod['namespace']
        if ns not in groups:
            groups[ns] = {'namespace': ns, 'pods': 0, 'running': 0, 'restarts': 0, 'cpu_m': 0, 'latest_created': pod['created'], '_time': stamp}
        g = groups[ns]
        g['pods'] += 1
        g['running'] += pod['phase'] == 'Running'
        g['restarts'] += pod['restarts']
        g['cpu_m'] += parse_cpu(pod['cpu'])
        if stamp > g['_time']:
            g['_time'] = stamp
            g['latest_created'] = pod['created']
    return [{k: v for k, v in g.items() if not k.startswith('_')} for g in sorted(groups.values(), key=lambda x: (x['namespace'].casefold(), x['namespace']))]

def render_report(title: str, pods: list[dict]) -> str:
    if not isinstance(title, str):
        raise ValueError('invalid title')
    rows = summarize_pods(pods)
    body = ''.join(('<tr><td>' + html.escape(str(g['namespace']), quote=True) + '</td><td>' + str(g['pods']) + '</td><td>' + str(g['running']) + '</td><td>' + str(g['restarts']) + '</td><td>' + str(g['cpu_m']) + '</td><td>' + html.escape(g['latest_created'], quote=True) + '</td></tr>' for g in rows))
    return '<h1>' + html.escape(title, quote=True) + '</h1><table><thead><tr><th>Namespace</th><th>Pods</th><th>Running</th><th>Restarts</th><th>CPU (m)</th><th>Latest</th></tr></thead><tbody>' + body + '</tbody></table>'

