import sqlite3

def list_counseling_sessions(conn: sqlite3.Connection, client_id: int | None=None, status: str | None=None, search: str='', sort_by: str='scheduled_at', descending: bool=False, limit: int=20, offset: int=0) -> list[dict]:
    if client_id is not None and (isinstance(client_id, bool) or not isinstance(client_id, int) or client_id <= 0):
        raise ValueError('invalid client_id')
    if status is not None and status not in {'scheduled', 'completed', 'cancelled'}:
        raise ValueError('invalid status')
    if sort_by not in {'scheduled_at', 'client_name', 'minutes', 'id'}:
        raise ValueError('invalid sort_by')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    columns = {'scheduled_at': 's.scheduled_at', 'client_name': 'c.name', 'minutes': 's.minutes', 'id': 's.id'}
    clauses = []
    parameters = []
    if client_id is not None:
        clauses.append('s.client_id = ?')
        parameters.append(client_id)
    if status is not None:
        clauses.append('s.status = ?')
        parameters.append(status)
    text = search.strip()
    if text:
        clauses.append('(LOWER(c.name) LIKE LOWER(?) OR LOWER(s.notes) LIKE LOWER(?))')
        pattern = '%' + text + '%'
        parameters.extend([pattern, pattern])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    query = 'SELECT s.id, c.name, s.scheduled_at, s.status, s.minutes FROM sessions s JOIN clients c ON c.id = s.client_id' + where + f' ORDER BY {columns[sort_by]} {direction}, s.id ASC LIMIT ? OFFSET ?'
    parameters.extend([limit, offset])
    rows = conn.execute(query, parameters).fetchall()
    return [{'id': row[0], 'client_name': row[1], 'scheduled_at': row[2], 'status': row[3], 'minutes': row[4]} for row in rows]

