    name, platform, attempt_text = (parts[0], parts[2], parts[4])
    if not name or not platform or (not attempt_text) or (not attempt_text.isdecimal()):
        raise ValueError('invalid reference')
    attempt = int(attempt_text)
    if attempt < 1:
        raise ValueError('invalid attempt')
    return {'name': name, 'platform': platform, 'attempt': attempt}

def build_manifest(records: list[dict]) -> dict:
    groups = {}
    for record in records:
        if not isinstance(record, dict) or set(record) != {'ref', 'size', 'state'}:
            raise ValueError('invalid record')
        if isinstance(record['size'], bool) or not isinstance(record['size'], int) or record['size'] < 0:
            raise ValueError('invalid size')
        if record['state'] not in {'pending', 'success', 'failure'}:
            raise ValueError('invalid state')
