        key = (parsed['name'], parsed['platform'])
        if key not in groups:
            groups[key] = {'name': key[0], 'platform': key[1], 'total_bytes': 0, 'attempts': set(), 'latest_attempt': 0, 'latest_state': None, 'states': {'pending': 0, 'success': 0, 'failure': 0}}
        group = groups[key]
