        group['states'][record['state']] += 1
        if parsed['attempt'] >= group['latest_attempt']:
            group['latest_attempt'] = parsed['attempt']
            group['latest_state'] = record['state']
    artifacts = []
    for key in sorted(groups):
        group = groups[key]
        artifacts.append({'name': group['name'], 'platform': group['platform'], 'total_bytes': group['total_bytes'], 'attempts': sorted(group['attempts']), 'latest_state': group['latest_state'], 'states': group['states']})
    return {'artifact_count': len(artifacts), 'artifacts': artifacts}

