    if not isinstance(supplied_secret, str):
        raise ValueError('invalid secret')
    if not isinstance(documents, list) or any((not isinstance(item, str) for item in documents)):
        raise ValueError('invalid documents')
    if not isinstance(query, str) or not query:
        raise ValueError('invalid query')
    try:
        expected = _derive(supplied_secret, account['salt'])
        valid = hmac.compare_digest(expected, account['credential'])
    except (KeyError, TypeError, ValueError):
        valid = False
    if not valid:
        raise PermissionError('invalid credentials')
    needle = query.casefold()
    return [item for item in documents if needle in item.casefold()]

