from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import math
from collections.abc import Mapping

def render_permit_table(records: list[dict[str, object]], page: int=1, page_size: int=10) -> str:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    rows = []
    total = Decimal('0')
    for record in records:
        if not isinstance(record, Mapping):
            raise ValueError('invalid record')
        try:
            permit_id = record['permit_id']
            resident = record['resident']
            zone = record['zone']
            status = record['status']
            fee = record['annual_fee']
        except KeyError as exc:
            raise ValueError('missing field') from exc
        if not all((isinstance(value, str) for value in (permit_id, resident, zone, status))):
            raise ValueError('invalid text field')
        if status not in ('active', 'expired'):
            raise ValueError('invalid status')
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or (not math.isfinite(fee)) or (fee < 0):
            raise ValueError('invalid fee')
        try:
            amount = Decimal(str(fee))
        except InvalidOperation as exc:
            raise ValueError('invalid fee') from exc
        total += amount
        rows.append((permit_id, resident, zone, status, amount))
    rows.sort(key=lambda row: (row[2], row[1].casefold(), row[0]))
    count = len(rows)
    pages = max(1, (count + page_size - 1) // page_size)
    selected = rows[(page - 1) * page_size:page * page_size]
    body = ''.join((f"<tr><td>{permit_id}</td><td>{resident}</td><td>{zone}</td><td>{status}</td><td>${amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP):.2f}</td></tr>" for permit_id, resident, zone, status, amount in selected))
    formatted_total = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return f'<div class="permits"><p>Page {page} of {pages} ({count} permits)</p><table><thead><tr><th>Permit</th><th>Resident</th><th>Zone</th><th>Status</th><th>Annual fee</th></tr></thead><tbody>{body}</tbody></table><p>Total annual fees: ${formatted_total:.2f}</p></div>'

