from datetime import datetime, timezone
import requests

def _instant(value):
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
        if parsed.tzinfo is None:
            raise ValueError
        return parsed.astimezone(timezone.utc)
    except (TypeError, ValueError, OverflowError):
        raise ValueError('invalid timestamp')

def _stamp(value):
    return value.strftime('%Y-%m-%dT%H:%M:%SZ')

def fetch_team_events(api_url: str, team_id: str, since: str, token: str) -> list[dict]:
    response = requests.get(api_url.rstrip('/') + '/teams/' + team_id + '/activity', params={'since': since}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('activity request failed with status ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('events'), list):
        raise ValueError('invalid response shape')
    result = []
    for event in payload['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('id', 'user', 'type', 'timestamp', 'duration_minutes')
        if any((key not in event for key in required)):
            raise ValueError('invalid event')
        if not all((isinstance(event[key], str) for key in ('id', 'user', 'type'))):
            raise ValueError('invalid event')
        duration = event['duration_minutes']
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid event')
        instant = _instant(event['timestamp'])
        result.append({'id': event['id'], 'user': event['user'], 'type': event['type'], 'timestamp': _stamp(instant), 'duration_minutes': duration})
    result.sort(key=lambda item: (item['timestamp'], item['id']))
    return result

def summary_team_activity(events: list[dict], window_minutes: int=60) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    size = window_minutes * 60
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        try:
            instant = _instant(event['timestamp'])
            user = event['user']
            kind = event['type']
            duration = event['duration_minutes']
        except (KeyError, TypeError):
            raise ValueError('invalid event')
        if not isinstance(user, str) or not isinstance(kind, str) or isinstance(duration, bool) or (not isinstance(duration, (int, float))) or (duration < 0):
            raise ValueError('invalid event')
        epoch = int(instant.timestamp())
        start = epoch - epoch % size
        users = groups.setdefault(start, {})
        info = users.setdefault(user, {'minutes': 0, 'events': 0, 'types': {}})
        info['minutes'] += duration
        info['events'] += 1
        info['types'][kind] = info['types'].get(kind, 0) + 1
    output = []
    for start in sorted(groups):
        users = {}
        for user in sorted(groups[start]):
            old = groups[start][user]
            users[user] = {'minutes': old['minutes'], 'events': old['events'], 'types': {key: old['types'][key] for key in sorted(old['types'])}}
        output.append({'start': _stamp(datetime.fromtimestamp(start, timezone.utc)), 'users': users})
    return output

