        raise ValueError('records must be a list')
    allowed = {'resident_id', 'name', 'status', 'bed', 'days'}
    for record in records:
        if not isinstance(record, dict) or set(record) != allowed:
            raise ValueError('invalid record')
        if type(record['resident_id']) is not int or record['resident_id'] < 0:
            raise ValueError('invalid resident id')
        if not isinstance(record['name'], str) or not record['name']:
            raise ValueError('invalid name')
        if record['status'] not in ('active', 'released', 'medical'):
            raise ValueError('invalid status')
        if record['bed'] is not None and (not isinstance(record['bed'], str)):
            raise ValueError('invalid bed')
        if type(record['days']) is not int or record['days'] < 0:
            raise ValueError('invalid days')

