    if type(offset) is not int or offset < 0 or type(limit) is not int or (not 1 <= limit <= 100):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid state') from exc
    try:
        _validate(records)
    except Exception as exc:
        raise ValueError('invalid state') from exc
    total = len(records)
    if offset > total:
        raise ValueError('offset out of range')
    ordered = sorted(records, key=lambda r: (r['name'].casefold(), r['resident_id']))
    counts = {'active': 0, 'released': 0, 'medical': 0}
    for record in records:
        counts[record['status']] += 1
    return {'total': total, 'by_status': counts, 'residents': ordered[offset:offset + limit]}

