def fetch_delivery_events(api_base: str, token: str, start: str, end: str, page_size: int=100) -> list[dict]:
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('page_size must be positive')
    url = api_base.rstrip('/') + '/v1/deliveries/events'
    headers = {'Authorization': 'Bearer ' + token, 'Accept': 'application/json'}
    result = []
    cursor = None
    while True:
        params = {'start': start, 'end': end, 'limit': page_size}
        if cursor:
            params['cursor'] = cursor
        response = requests.get(url, params=params, headers=headers)
        if response.status_code != 200:
            raise RuntimeError('delivery service returned an error')
        data = response.json()
        if not isinstance(data, dict) or not isinstance(data.get('events'), list):
            raise ValueError('invalid response')
        for event in data['events']:
            if not isinstance(event, dict) or any((key not in event for key in ('id', 'email', 'status', 'timestamp'))):
                raise ValueError('invalid event')
            result.append(event)
        cursor = data.get('next_cursor')
        if not cursor:
            return result

def summarize_delivery_events(events: list[dict], window_minutes: int=60) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    groups = {}
    span = window_minutes * 60
    for event in events:
        if not isinstance(event, dict) or any((key not in event for key in ('id', 'email', 'status', 'timestamp'))):
            raise ValueError('invalid event')
        email = event['email']
        if not isinstance(email, str) or email.count('@') != 1 or (not email.split('@', 1)[1]):
            raise ValueError('invalid email')
        try:
            stamp = event['timestamp']
            if stamp.endswith('Z'):
                stamp = stamp[:-1] + '+00:00'
            dt = datetime.fromisoformat(stamp).astimezone(timezone.utc)
            epoch = int(dt.timestamp())
        except (AttributeError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid timestamp')
        bucket = epoch - epoch % span
        domain = email.split('@', 1)[1]
        key = (bucket, domain)
        if key not in groups:
            groups[key] = {}
        status = event['status']
        groups[key][status] = groups[key].get(status, 0) + 1
    output = []
    for (bucket, domain), counts in sorted(groups.items(), key=lambda item: (item[0][0], item[0][1])):
        ordered = {key: counts[key] for key in sorted(counts)}
        output.append({'window_start': datetime.fromtimestamp(bucket, timezone.utc).isoformat().replace('+00:00', 'Z'), 'domain': domain, 'counts': ordered, 'total': sum(ordered.values())})
    return output

