    seen_ids = set()
    for student in root:
        if student.tag != 'student':
            raise ValueError('invalid student')
        sid, name = (student.get('id'), student.get('name'))
        if not sid or name is None or sid in seen_ids:
            raise ValueError('invalid student')
        seen_ids.add(sid)
        courses = []
        seen_courses = set()
        for item in student:
            if item.tag != 'enrollment':
                raise ValueError('invalid enrollment')
            course, credits, day, start, end, status = (item.get(x) for x in ('course', 'credits', 'day', 'start', 'end', 'status'))
            if not course or course in seen_courses or status not in ('enrolled', 'dropped') or (day not in _DAY) or (not _TIME.fullmatch(start or '')) or (not _TIME.fullmatch(end or '')):
