        conflicts = []
        for i, left in enumerate(courses):
            for right in courses[i + 1:]:
                if left['day'] == right['day'] and left['start'] < right['end'] and (right['start'] < left['end']):
                    conflicts.append([left['course'], right['course']])
        students.append({'id': sid, 'name': name, 'courses': courses, 'credits': sum((c['credits'] for c in courses)), 'conflicts': conflicts})
