            if not rows or rows[0] != ['tag', 'flight', 'status', 'weight_kg']:
                raise ValueError('invalid header')
            for row in rows[1:]:
                if len(row) != 4:
                    raise ValueError('invalid row')
                tag, flight, status, weight_text = row
                if not tag or not flight:
                    raise ValueError('empty field')
                try:
                    weight = float(weight_text)
                except ValueError:
                    raise ValueError('invalid weight')
                if weight < 0:
                    raise ValueError('invalid weight')
                item = totals.setdefault(tag, {'tag': tag, 'pieces': 0, 'total': 0.0, 'flights': set(), 'status': ''})
                item['pieces'] += 1
                item['total'] += weight
                item['flights'].add(flight)
                item['status'] = status
    result = []
