import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def write_underwriting_summary(records: list[dict], output_name: str, base_dir: str, page: int=1, page_size: int=10) -> str:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('region', 'status', 'premium'))):
            raise ValueError('invalid record')
        if not isinstance(record['region'], str) or not isinstance(record['status'], str):
            raise ValueError('invalid record')
        premium = record['premium']
        if isinstance(premium, bool) or not isinstance(premium, (int, float)):
            raise ValueError('invalid record')
        try:
            amount = Decimal(str(premium))
        except InvalidOperation:
            raise ValueError('invalid record')
        if amount < 0 or not amount.is_finite():
            raise ValueError('invalid record')
        if record['status'] == 'approved':
            item = groups.setdefault(record['region'], [0, Decimal('0')])
            item[0] += 1
            item[1] += amount
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1][1], pair[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    lines = ['region\tcount\ttotal_premium\n']
    for region, (count, total) in selected:
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        lines.append(f'{region}\t{count}\t{rounded:.2f}\n')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, output_name))
    if target == base or not target.startswith(base + os.sep):
        raise ValueError('output path is outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.writelines(lines)
    return target

