                    raise ValueError('each record must contain four fields')
                writer.writerow(record)
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

