def test_empty_matching_attempts():
    requester = {"id": "u", "role": "proctor", "tenant_id": "t"}
    exam = {"id": "e", "owner_id": "x", "tenant_id": "t", "title": "Empty"}
    result = generate_proctor_report(requester, exam, [], page=1, page_size=10)
    assert result["total"] == 0
    assert result["average_score"] is None
    assert result["highest_score"] is None
