    attempts = [
        {"exam_id": "e", "candidate_id": "z", "status": "completed", "score": 90, "submitted_at": "1"},
        {"exam_id": "e", "candidate_id": "a", "status": "completed", "score": 90, "submitted_at": "1"},
        {"exam_id": "e", "candidate_id": "m", "status": "completed", "score": 88, "submitted_at": "1"},
    ]
    result = generate_proctor_report(requester, exam, attempts)
    assert result["average_score"] == 89.33
