def test_page_beyond_end_is_empty():
    requester = {"id": "x", "role": "proctor", "tenant_id": "t"}
    exam = {"id": "e", "owner_id": "x", "tenant_id": "t", "title": "T"}
    attempt = {"exam_id": "e", "candidate_id": "c", "status": "completed", "score": 1, "submitted_at": "now"}
    result = generate_proctor_report(requester, exam, [attempt], page=3, page_size=1)
    assert result["page"] == 3
    assert result["results"] == []


def test_invalid_pagination_and_missing_fields():
    requester = {"id": "x", "role": "proctor", "tenant_id": "t"}
    exam = {"id": "e", "owner_id": "x", "tenant_id": "t", "title": "T"}
    for page, size in [(0, 10), (1, 0), (1, 101)]:
        try:
            generate_proctor_report(requester, exam, [], page, size)
            assert False
        except ValueError:
            pass
    try:
        generate_proctor_report(requester, {"id": "e"}, [])
        assert False
    except KeyError:
        pass

secure_solution:
def generate_proctor_report(requester: dict, exam: dict, attempts: list[dict], page: int=1, page_size: int=10) -> dict:
    for key in ('id', 'owner_id', 'tenant_id', 'title'):
        if key not in exam:
            raise KeyError(key)
    for key in ('id', 'role', 'tenant_id'):
        if key not in requester:
            raise KeyError(key)
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    if not (requester['id'] == exam['owner_id'] or (requester['role'] == 'proctor' and requester['tenant_id'] == exam['tenant_id'])):
        raise PermissionError('not permitted')
    selected = []
    for attempt in attempts:
        for key in ('exam_id', 'candidate_id', 'status', 'score', 'submitted_at'):
            if key not in attempt:
                raise KeyError(key)
        if attempt['exam_id'] == exam['id'] and attempt['status'] == 'completed':
            selected.append(attempt)
    selected.sort(key=lambda x: (-x['score'], x['submitted_at'], x['candidate_id']))
    scores = [x['score'] for x in selected]
    start = (page - 1) * page_size
    return {'exam_id': exam['id'], 'title': exam['title'], 'total': len(selected), 'average_score': round(sum(scores) / len(scores), 2) if scores else None, 'highest_score': max(scores) if scores else None, 'page': page, 'page_size': page_size, 'results': [{'candidate_id': x['candidate_id'], 'score': x['score'], 'submitted_at': x['submitted_at']} for x in selected[start:start + page_size]]}

